    event_time_zone text DEFAULT 'America/New_York'::text NOT NULL
);


--
-- Name: TABLE raffle_event; Type: COMMENT; Schema: outdateddbsnapshotoct2024; Owner: -
--

COMMENT ON TABLE outdateddbsnapshotoct2024.raffle_event IS 'Meetup raffle events; event_show_combo=true rows appear in Get My Raffle; tickets only between host_event_raffle_start and host_event_raffle_end.';


--
-- Name: COLUMN raffle_event.event_time_zone; Type: COMMENT; Schema: outdateddbsnapshotoct2024; Owner: -
--

COMMENT ON COLUMN outdateddbsnapshotoct2024.raffle_event.event_time_zone IS 'IANA time zone of the event (America/New_York, America/Los_Angeles, …); times below are shown in this zone.';


