--
-- Name: raffle_event_local; Type: VIEW; Schema: outdateddbsnapshotoct2024; Owner: -
--

CREATE VIEW outdateddbsnapshotoct2024.raffle_event_local AS
 SELECT event_id,
    event_show_combo,
    raffle_host_id,
    event_title,
    event_time_zone,
    (event_night_datetime AT TIME ZONE event_time_zone) AS event_night_local,
    (host_event_raffle_start AT TIME ZONE event_time_zone) AS raffle_start_local,
    (host_event_raffle_end AT TIME ZONE event_time_zone) AS raffle_end_local,
    event_build_n_address,
    event_url
   FROM outdateddbsnapshotoct2024.raffle_event e;


