    tuta_dates_enabled boolean DEFAULT true NOT NULL,
    tuta_notes_enabled boolean DEFAULT true NOT NULL,
    tuta_albums_enabled boolean DEFAULT true NOT NULL,
    zip_folder text,
    CONSTRAINT user_customization_custom_music_url_limit_chk CHECK (((custom_music_url IS NULL) OR ((cardinality(custom_music_url) <= 10) AND ((array_ndims(custom_music_url) IS NULL) OR (array_ndims(custom_music_url) = 1))))),
    CONSTRAINT user_customization_lyric_volume_range_chk CHECK (((lyric_volume >= 0) AND (lyric_volume <= 100))),
    CONSTRAINT user_customization_mynote_color_index_range_chk CHECK ((((mynote_content_bg_index IS NULL) OR ((mynote_content_bg_index >= 0) AND (mynote_content_bg_index <= 6))) AND ((mynote_font_color_index IS NULL) OR ((mynote_font_color_index >= 0) AND (mynote_font_color_index <= 6))) AND ((mynote_text_highlight_index IS NULL) OR ((mynote_text_highlight_index >= 0) AND (mynote_text_highlight_index <= 6))))),
    CONSTRAINT user_customization_mynote_editor_caret_pos_range_chk CHECK (((mynote_editor_caret_pos IS NULL) OR (mynote_editor_caret_pos >= 0))),
    CONSTRAINT user_customization_mynote_editor_font_size_pt_range_chk CHECK (((mynote_editor_font_size_pt IS NULL) OR ((mynote_editor_font_size_pt >= 4) AND (mynote_editor_font_size_pt <= 128)))),
    CONSTRAINT user_customization_mynote_editor_font_size_range_chk CHECK (((mynote_editor_font_size IS NULL) OR ((mynote_editor_font_size >= 4) AND (mynote_editor_font_size <= 128)))),
    CONSTRAINT user_customization_mynote_font_size_range_chk CHECK (((mynote_font_size IS NULL) OR ((mynote_font_size >= 4) AND (mynote_font_size <= 128)))),
    CONSTRAINT user_customization_mynote_note_scroll_top_range_chk CHECK (((mynote_note_scroll_top IS NULL) OR (mynote_note_scroll_top >= 0))),
    CONSTRAINT user_customization_volume_range_chk CHECK (((volume >= 0) AND (volume <= 100)))
);


