--
-- Name: user_education_verifications_summary; Type: VIEW; Schema: outdateddbsnapshotoct2024; Owner: -
--

CREATE VIEW outdateddbsnapshotoct2024.user_education_verifications_summary AS
 SELECT id,
    user_id,
    is_verified,
    COALESCE(((digest_record -> 'verification_summary'::text) ->> 'verified_institution_name'::text), ((raw_academic_record -> 'institution'::text) ->> 'name'::text)) AS college_name,
    COALESCE(((digest_record -> 'verification_summary'::text) ->> 'highest_degree_earned'::text), (((raw_academic_record -> 'degrees'::text) -> 0) ->> 'title'::text)) AS degree,
    COALESCE(((digest_record -> 'verification_summary'::text) ->> 'primary_major'::text), (((raw_academic_record -> 'degrees'::text) -> 0) ->> 'major'::text)) AS major,
    COALESCE(((digest_record -> 'verification_summary'::text) ->> 'graduation_date'::text), (((raw_academic_record -> 'degrees'::text) -> 0) ->> 'confer_date'::text)) AS graduation_date,
    ((digest_record -> 'verification_summary'::text) ->> 'cumulative_gpa'::text) AS cumulative_gpa,
    measureone_individual_id,
    measureone_datarequest_id,
    updated_at
   FROM outdateddbsnapshotoct2024.user_education_verifications u;


