--
-- Name: yearly_bill; Type: TABLE; Schema: outdateddbsnapshotoct2024; Owner: -
--

CREATE TABLE outdateddbsnapshotoct2024.yearly_bill (
    yearly_bill_id bigint NOT NULL,
    singles_id bigint NOT NULL,
    bill_year integer NOT NULL,
    bill_month integer,
    row_index integer NOT NULL,
    bill_description text DEFAULT ''::text NOT NULL,
    due_month_day integer,
    amount text DEFAULT ''::text NOT NULL,
    bill_type text DEFAULT 'Manual'::text NOT NULL,
    action text,
    paid_record_id bigint,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    storage_backend text DEFAULT 'onedrive'::text NOT NULL,
    bill_icon text,
    email_scan_pending boolean DEFAULT false NOT NULL,
    CONSTRAINT yearly_bill_action_check CHECK (((action IS NULL) OR (action = ANY (ARRAY['Not Paid'::text, 'Paid'::text])))),
    CONSTRAINT yearly_bill_bill_month_check CHECK (((bill_month IS NULL) OR ((bill_month >= 1) AND (bill_month <= 12)))),
    CONSTRAINT yearly_bill_bill_type_check CHECK ((bill_type = ANY (ARRAY['Auto'::text, 'Manual'::text]))),
    CONSTRAINT yearly_bill_bill_year_check CHECK (((bill_year >= 2000) AND (bill_year <= 2100))),
    CONSTRAINT yearly_bill_due_month_day_check CHECK (((due_month_day IS NULL) OR ((due_month_day >= 1) AND (due_month_day <= 31)))),
    CONSTRAINT yearly_bill_row_index_check CHECK ((row_index >= 1)),
    CONSTRAINT yearly_bill_storage_backend_check CHECK ((storage_backend = ANY (ARRAY['onedrive'::text, 'usb'::text])))
);


--
-- Name: TABLE yearly_bill; Type: COMMENT; Schema: outdateddbsnapshotoct2024; Owner: -
--

COMMENT ON TABLE outdateddbsnapshotoct2024.yearly_bill IS 'TutaNotes Bill Schedule Yearly rows; one forever slice per (singles_id, bill_year).';


--
-- Name: COLUMN yearly_bill.bill_year; Type: COMMENT; Schema: outdateddbsnapshotoct2024; Owner: -
--

COMMENT ON COLUMN outdateddbsnapshotoct2024.yearly_bill.bill_year IS 'Calendar year of this history slice (cloned forward without action/paid_record_id).';


--
-- Name: COLUMN yearly_bill.bill_month; Type: COMMENT; Schema: outdateddbsnapshotoct2024; Owner: -
--

COMMENT ON COLUMN outdateddbsnapshotoct2024.yearly_bill.bill_month IS 'Due month 1–12 within the year.';


--
-- Name: COLUMN yearly_bill.due_month_day; Type: COMMENT; Schema: outdateddbsnapshotoct2024; Owner: -
--

COMMENT ON COLUMN outdateddbsnapshotoct2024.yearly_bill.due_month_day IS 'Due day 1–31 within bill_month (due_month_day).';


--
-- Name: COLUMN yearly_bill.action; Type: COMMENT; Schema: outdateddbsnapshotoct2024; Owner: -
--

COMMENT ON COLUMN outdateddbsnapshotoct2024.yearly_bill.action IS 'Manual only: Not Paid / Paid. NULL for Auto or unset. Not cloned to next year.';


--
-- Name: COLUMN yearly_bill.paid_record_id; Type: COMMENT; Schema: outdateddbsnapshotoct2024; Owner: -
--

COMMENT ON COLUMN outdateddbsnapshotoct2024.yearly_bill.paid_record_id IS 'FK to paid_record when Bills/Receipts content exists for this row.';


--
-- Name: COLUMN yearly_bill.storage_backend; Type: COMMENT; Schema: outdateddbsnapshotoct2024; Owner: -
--

COMMENT ON COLUMN outdateddbsnapshotoct2024.yearly_bill.storage_backend IS 'Vault side: onedrive (TutaDrive/OneDrive Cloud) or usb.';


--
-- Name: COLUMN yearly_bill.bill_icon; Type: COMMENT; Schema: outdateddbsnapshotoct2024; Owner: -
--

COMMENT ON COLUMN outdateddbsnapshotoct2024.yearly_bill.bill_icon IS 'Icon name picked for this Yearly bill row (security icon set). NULL = not chosen ("?").';


--
-- Name: COLUMN yearly_bill.email_scan_pending; Type: COMMENT; Schema: outdateddbsnapshotoct2024; Owner: -
--

COMMENT ON COLUMN outdateddbsnapshotoct2024.yearly_bill.email_scan_pending IS 'true = row added by Auto Scan Emails and not yet approved (red dashed + Approve button).';


